import 'dart:convert';
import 'dart:io';

import 'package:flutter_test/flutter_test.dart';
import 'package:image/image.dart' as img;

import 'package:opencadirrigation/app/i18n.dart' show rtlLanguages, supportedLanguages;
import 'package:opencadirrigation/app/version.dart' show appRepositoryUrl, appVersion;

import '../tool/site.dart';

/// Guards the web launch metadata for opencadirrigation.com: one entry page
/// per interface language (en at /, the others under /<code>/: /pt/, /es/,
/// /de/, /zh/, …) generated by tool/gen_site.dart, the redirect left at the
/// old /en/, manifest, icons, robots, sitemap, 404, the files for language
/// models (llms.txt, llms-full.txt), the IndexNow key and brand assets.
void main() {
  const site = 'https://opencadirrigation.com/';
  (int, int) size(String path) {
    final i = img.decodePng(File(path).readAsBytesSync());
    expect(i, isNotNull, reason: path);
    return (i!.width, i.height);
  }

  Map<String, dynamic> jsonLdOf(String html) {
    final ld = RegExp(r'<script type="application/ld\+json">([\s\S]*?)</script>').firstMatch(html)!.group(1)!;
    return jsonDecode(ld) as Map<String, dynamic>;
  }

  test('design worker bundle is compiled next to the web app', () {
    // tool/build_worker.sh compiles lib/worker/design_worker.dart to web/design_worker.js
    final f = File('web/design_worker.js');
    expect(f.existsSync(), isTrue, reason: 'run tool/build_worker.sh');
    expect(f.lengthSync(), greaterThan(100000));
    expect(File('web/design_worker.js.deps').existsSync(), isFalse);
  });

  test('the pages, sitemap, 404, site script and hosting configuration match the generator (tool/gen_site.dart)', () {
    for (final e in {for (final e in renderSite().entries) 'web/${e.key}': e.value, ...renderRepositoryFiles()}.entries) {
      final f = File(e.key);
      expect(f.existsSync(), isTrue, reason: e.key);
      expect(f.readAsStringSync(), e.value, reason: '${f.path} is out of date: run dart run tool/gen_site.dart');
    }
  });

  test('root index.html carries SEO, Open Graph, Twitter, icons, manifest and JSON-LD', () {
    final html = File('web/index.html').readAsStringSync();
    expect(html, contains('<base href="\$FLUTTER_BASE_HREF">'));
    expect(html, contains('<html lang="en">'), reason: 'English is the default: the root page is the English one');
    expect(html, contains('<link rel="canonical" href="$site">'));
    for (final needle in [
      'og:title',
      'og:description',
      'og:url',
      'og:type',
      'twitter:card',
      'name="description"',
      'name="viewport"',
      'rel="manifest"',
      'rel="apple-touch-icon"',
      'hreflang="en"',
      'hreflang="es"',
      'hreflang="pt-BR"',
      'hreflang="zh-CN"',
      // the bare languages too: Portuguese and Chinese readers outside Brazil and mainland China
      'hreflang="pt"',
      'hreflang="zh"',
      'hreflang="x-default"',
      'theme-color',
      'name="robots"',
    ]) {
      expect(html, contains(needle), reason: needle);
    }
    for (final l in siteLanguages) {
      expect(html, contains('<link rel="alternate" hreflang="${l.tag}" href="${l.url}">'), reason: l.code);
    }
    expect(html, contains('content="${site}og-image.png"'));
    expect(html, contains('<script src="site.js?v='), reason: 'site.js starts flutter_bootstrap.js when the app is wanted');
    expect(File('web/site.js').readAsStringSync(), allOf(contains("boot.src = 'flutter_bootstrap.js'"), contains('flutter-first-frame')));
    expect(html, contains('data-ga="$analyticsId"'), reason: 'the measurement id goes to site.js, set when the pages are generated');

    final graph = jsonLdOf(html)['@graph'] as List;
    expect(graph.map((e) => (e as Map)['@type']), containsAll(['Organization', 'WebSite', 'WebPage', 'WebApplication', 'SoftwareSourceCode', 'BreadcrumbList', 'FAQPage', 'HowTo', 'ItemList']));
    final app = graph.firstWhere((e) => (e as Map)['@type'] == 'WebApplication') as Map;
    expect(app['url'], site);
    expect(app['name'], 'OpenCADIrrigation');
    expect(app['isAccessibleForFree'], isTrue);
    // open source: the licence, the repository and what it builds
    expect(app['license'], 'https://opensource.org/license/mit');
    final code = graph.firstWhere((e) => (e as Map)['@type'] == 'SoftwareSourceCode') as Map;
    expect(code['codeRepository'], appRepositoryUrl);
    expect(code['license'], app['license']);
    expect(code['targetProduct'], {'@id': '$site#app'});
    expect((graph.firstWhere((e) => (e as Map)['@type'] == 'Organization') as Map)['sameAs'], [appRepositoryUrl]);
    expect(html, contains('<link rel="alternate" type="text/markdown" href="${site}llms.txt"'), reason: 'points language models to llms.txt');
    expect(html, isNot(contains('OpenCadIrrigation')));
    // title and description lengths search engines display in full
    final title = RegExp(r'<title>(.*?)</title>').firstMatch(html)!.group(1)!;
    expect(title.length, inInclusiveRange(30, 65), reason: title);
    // search results cut the snippet at about 160 characters: every language fits
    for (final l in siteLanguages) {
      final page = File('web/${l.file}').readAsStringSync();
      final desc = RegExp(r'<meta name="description" content="(.*?)">').firstMatch(page)!.group(1)!;
      final text = desc.replaceAll('&amp;', '&').replaceAll('&quot;', '"');
      expect(text.length, inInclusiveRange(50, 160), reason: '${l.code}: $text');
    }
  });

  test('the page body is real, readable content for crawlers and non-JS visitors', () {
    for (final l in siteLanguages) {
      final html = File('web/${l.file}').readAsStringSync();
      final t = siteText(l.code);
      expect(html, contains('<h1>${t.h1}</h1>'), reason: l.code);
      expect(RegExp(r'<h2 ').allMatches(html).length, 5, reason: '${l.code}: ai, features, how, examples, faq');
      // the AI assistant first: its own section, before the feature list
      expect(html, contains('<h2 id="oci-ai">${t.aiTitle}</h2>'), reason: l.code);
      expect(html.indexOf('id="oci-ai"'), lessThan(html.indexOf('id="oci-features"')), reason: l.code);
      for (final (name, _) in t.aiPoints) {
        expect(html, contains('<h3>$name</h3>'), reason: '${l.code} $name');
      }
      for (final (name, _) in t.features) {
        expect(html, contains('<h3>$name</h3>'), reason: '${l.code} $name');
      }
      for (final ex in t.examples) {
        expect(html, contains('href="${l.url}?example=${ex.id}"'), reason: '${l.code} ${ex.id}');
      }
      expect(html, contains('href="${l.url}?tutorial=1"'));
      expect(html, contains('<dt>${t.faq.first.$1}</dt>'));
      expect(html, contains('id="oci-landing"'));
      expect(html, contains('<script src="site.js?v='), reason: '${l.code}: the page logic is site.js');
      expect(html, contains('<noscript>'));
      // links to the other language versions
      for (final o in siteLanguages) {
        if (o.code != l.code) expect(html, contains('<a href="${o.url}" hreflang="${o.tag}"'), reason: '${l.code} → ${o.code}');
      }
    }
  });

  test('the app loads when asked for: a first visit gets the light page alone', () {
    final script = File('web/site.js').readAsStringSync();
    expect(script, contains("boot.src = 'flutter_bootstrap.js'"));
    expect(script, contains("landing.setAttribute('hidden', '')"), reason: 'hidden, not removed, on first frame');
    expect(script, contains("var prefix = 'opencadirrigation.';"), reason: 'returning users: the prefix of the app storage');
    final manifest = jsonDecode(File('web/manifest.json').readAsStringSync()) as Map<String, dynamic>;
    final appAddresses = [manifest['start_url'] as String, for (final s in manifest['shortcuts'] as List) (s as Map)['url'] as String];
    for (final l in siteLanguages) {
      final html = File('web/${l.file}').readAsStringSync();
      expect(html, isNot(contains('<script src="flutter_bootstrap.js"')), reason: '${l.code}: the page does not fetch the app by itself');
      expect(html, isNot(contains('rel="preload"')), reason: '${l.code}: the logo is found in the page with fetchpriority=high');
      expect(html, isNot(contains('<link rel="preconnect"')), reason: '${l.code}: no connection to the engine CDN until the app starts');
      // buttons and example links open the app in place
      expect(html, contains('<a class="primary" href="${l.url}" data-app>'), reason: l.code);
      expect(html, contains('<a href="${l.url}?tutorial=1" data-app>'), reason: l.code);
      expect(html, contains('<a href="${l.url}?ai=1" data-app>'), reason: '${l.code}: the AI assistant opens in place');
      for (final ex in siteText(l.code).examples) {
        expect(html, contains('<a href="${l.url}?example=${ex.id}" data-app>'), reason: '${l.code} ${ex.id}');
      }
      // addresses of the app (installed app, its shortcuts, deep links) start it without a click
      final params = RegExp(r'\[\?&\]\(([a-z|]+)\)=').firstMatch(script)!.group(1)!.split('|');
      for (final address in [...appAddresses, '${l.url}?example=garden', '${l.url}?tutorial=1', '${l.url}?ai=1', '${l.url}?lang=es']) {
        expect(Uri.parse(address.replaceFirst('./', site)).queryParameters.keys.any(params.contains), isTrue, reason: '${l.code}: $address');
      }
      // the logo: WebP in three widths, versioned by content
      for (final w in landingLogoWidths) {
        expect(html, contains('${landingLogo(w)} ${w}w'), reason: '${l.code} $w');
      }
      // the screenshot further down: lazy, sized (no layout shift), described in the page language
      final shot = RegExp(r'<img src="screenshots/[^>]*>').firstMatch(html)!.group(0)!;
      for (final w in landingShotWidths) {
        expect(shot, contains('${landingShot(w)} ${w}w'), reason: '${l.code} $w');
      }
      for (final attribute in ['loading="lazy"', 'decoding="async"', 'width="1440" height="900"', 'alt="${siteText(l.code).screenshotLabel}"']) {
        expect(shot, contains(attribute), reason: '${l.code}: $attribute');
      }
      expect(html.indexOf(shot), greaterThan(html.indexOf('id="oci-how"')), reason: '${l.code}: below the fold, not competing with the logo');
      // the source code, from every page
      expect(html, contains('<a href="$appRepositoryUrl">${siteText(l.code).sourceCode}</a>'), reason: l.code);
    }
    expect(File('lib/app/io/prefs_web.dart').readAsStringSync(), contains("'opencadirrigation.\$key'"));
    for (final w in landingLogoWidths) {
      final logo = img.decodeWebP(File('web/brand/logo-horizontal-$w.webp').readAsBytesSync());
      expect(logo, isNotNull, reason: '$w');
      expect(logo!.width, w);
      expect(logo.width / logo.height, closeTo(1040 / 349, 0.01), reason: 'same shape as the width/height of the img');
      expect(logo.numChannels, 4, reason: 'transparent, like the PNG');
    }
    expect(landingLogo(520), matches(RegExp(r'^brand/logo-horizontal-520\.webp\?v=[0-9a-f]{8}$')));
    for (final w in landingShotWidths) {
      final shot = img.decodeWebP(File('web/screenshots/design-$w.webp').readAsBytesSync());
      expect(shot, isNotNull, reason: '$w');
      expect((shot!.width, shot.height), (w, w * 900 ~/ 1440), reason: 'same shape as design-1440x900.png');
    }
    // our bootstrap: Flutter's loader without the deprecated service worker
    final bootstrap = File('web/flutter_bootstrap.js').readAsStringSync();
    expect(bootstrap, contains('{{flutter_js}}'));
    expect(bootstrap, contains('{{flutter_build_config}}'));
    expect(bootstrap, contains('_flutter.loader.load();'));
    expect(bootstrap, isNot(contains('serviceWorker')));
  });

  test('every page describes the app, its FAQ, steps and examples as JSON-LD in its own language', () {
    for (final l in siteLanguages) {
      final html = File('web/${l.file}').readAsStringSync();
      final t = siteText(l.code);
      final graph = (jsonLdOf(html)['@graph'] as List).cast<Map<String, dynamic>>();
      Map<String, dynamic> node(String type) => graph.firstWhere((e) => e['@type'] == type);
      final faq = node('FAQPage');
      expect(faq['inLanguage'], l.tag, reason: l.code);
      expect([for (final q in faq['mainEntity'] as List) (q as Map)['name']], [for (final (q, _) in t.faq) q], reason: l.code);
      expect(((faq['mainEntity'] as List).first as Map)['acceptedAnswer']['text'], t.faq.first.$2);
      expect(t.faq.first.$1, contains('OpenCADIrrigation'), reason: '${l.code}: the FAQ opens with what the app is');
      final how = node('HowTo');
      expect((how['step'] as List).length, t.how.length, reason: l.code);
      final examples = node('ItemList');
      expect(examples['numberOfItems'], t.examples.length);
      expect([for (final e in examples['itemListElement'] as List) (e as Map)['item']['url']], [for (final ex in t.examples) '${l.url}?example=${ex.id}'], reason: l.code);
      final app = node('WebApplication');
      expect(app['softwareVersion'], isNotEmpty);
      expect(app['featureList'], hasLength(t.features.length));
      for (final thing in app['about'] as List) {
        expect(((thing as Map)['sameAs'] as List).first, startsWith('https://en.wikipedia.org/wiki/'), reason: '${thing['name']}');
      }
      final page = node('WebPage');
      expect([for (final p in page['hasPart'] as List) (p as Map)['@id']], ['${l.url}#faq', '${l.url}#how', '${l.url}#examples']);
      expect(html, contains('<time datetime="$siteLastMod">'), reason: '${l.code}: visible date of the last update');
    }
  });

  test('llms.txt and llms-full.txt tell language models what the app is, in Markdown', () {
    final llms = File('web/llms.txt').readAsStringSync();
    final full = File('web/llms-full.txt').readAsStringSync();
    final en = siteText('en');
    // llmstxt.org: an H1 with the name, then a blockquote summary
    expect(llms, startsWith('# OpenCADIrrigation\n\n> ${en.faq.first.$2}\n'));
    expect(full, startsWith('# OpenCADIrrigation'));
    expect(RegExp(r'^## ', multiLine: true).allMatches(llms).length, greaterThanOrEqualTo(4));
    expect(llms, contains('(${site}llms-full.txt)'));
    for (final l in siteLanguages) {
      expect(llms, contains('(${l.url})'), reason: l.code);
      expect(full, contains('| ${l.url} |'), reason: l.code);
    }
    for (final ex in en.examples) {
      expect(llms, contains('($site?example=${ex.id})'), reason: ex.id);
      expect(full, contains('($site?example=${ex.id})'), reason: ex.id);
    }
    for (final (q, a) in en.faq) {
      expect(full, contains('### $q\n\n$a'));
    }
    for (final (name, _) in en.features) {
      expect(full, contains('### $name'));
    }
    for (final text in [llms, full]) {
      expect(text, contains('$appVersion, updated $siteLastMod'), reason: 'version and date stated');
      expect(text, isNot(contains('\$')), reason: 'no unexpanded interpolation');
      expect(text, contains('Open source under the MIT licence; source code (Dart and Flutter) at $appRepositoryUrl'));
    }
    expect(llms, contains('- [Source code]($appRepositoryUrl)'));
    // the reference covers what the page cannot hold
    for (final heading in ['## At a glance', '## AI assistant', '## Hydraulic engine', '## Pipe sizing and optimisation', '## File formats', '## Known limitations', '## Deep links']) {
      expect(full, contains(heading));
    }
    // the AI assistant is stated up front, for the assistants that answer "does it have AI?"
    expect(llms, contains('## AI assistant'));
    expect(llms, contains('($site?ai=1)'));
    expect(full.indexOf('## AI assistant'), lessThan(full.indexOf('## Hydraulic engine')));
  });

  test('IndexNow key file and humans.txt', () {
    expect(File('web/$indexNowKey.txt').readAsStringSync(), indexNowKey);
    expect(indexNowKey, matches(RegExp(r'^[0-9a-f]{32}$')));
    final humans = File('web/humans.txt').readAsStringSync();
    expect(humans, contains('Last update: $siteLastMod'));
    expect(humans, contains('${site}llms.txt'));
    expect(humans, contains('Source code: $appRepositoryUrl (MIT licence)'));
    for (final l in siteLanguages) {
      expect(humans, contains('(/${l.path})'), reason: l.code);
    }
  });

  test('every interface language of the app has its own entry page', () {
    expect([for (final l in siteLanguages) l.code], supportedLanguages);
    expect(siteLanguages.where((l) => l.isRoot).map((l) => l.code), ['en']);
    final en = siteText('en');
    for (final l in siteLanguages) {
      final t = siteText(l.code);
      expect(l.path, l.isRoot ? '' : '${l.code}/');
      expect(t.features.length, en.features.length, reason: l.code);
      expect(t.aiPoints.length, en.aiPoints.length, reason: l.code);
      expect(t.how.length, en.how.length, reason: l.code);
      expect(t.faq.length, en.faq.length, reason: l.code);
      expect([for (final e in t.examples) e.id], [for (final e in en.examples) e.id], reason: '${l.code}: same gallery, same order');
      for (final e in t.examples) {
        expect(e.title, isNotEmpty, reason: '${l.code} ${e.id}');
        expect(e.text, isNotEmpty, reason: '${l.code} ${e.id}');
      }
      if (l.code == 'en') continue;
      for (final (field, value, english) in [
        ('title', t.title, en.title),
        ('description', t.description, en.description),
        ('h1', t.h1, en.h1),
        ('intro', t.intro, en.intro),
        ('aiTitle', t.aiTitle, en.aiTitle),
        ('aiIntro', t.aiIntro, en.aiIntro),
        ('faq', t.faq.last.$2, en.faq.last.$2),
        ('notFoundText', t.notFoundText, en.notFoundText),
      ]) {
        expect(value, isNot(english), reason: '${l.code}.$field is still the English text');
      }
      expect(t.title, startsWith('OpenCADIrrigation'), reason: l.code);
    }
  });

  test('Arabic and Urdu pages read right to left', () {
    for (final l in siteLanguages) {
      final html = File('web/${l.file}').readAsStringSync();
      final rtl = rtlLanguages.contains(l.code);
      expect(html.contains('<main id="oci-landing" dir="rtl" '), rtl, reason: l.code);
      expect(html, contains('<html lang="${l.tag}">'), reason: 'the app keeps its own layout: no dir on <html>');
    }
  });

  test('the localised entry pages are rooted at the site root', () {
    for (final l in siteLanguages.where((l) => !l.isRoot)) {
      final html = File('web/${l.file}').readAsStringSync();
      expect(html, contains('<html lang="${l.tag}">'), reason: l.code);
      expect(html, contains('<base href="/">'), reason: 'the app and its assets live at the root');
      expect(html, contains('<link rel="canonical" href="${l.url}">'));
      expect(html, contains('<meta property="og:url" content="${l.url}">'));
      expect(html, contains('<meta property="og:locale" content="${l.ogLocale}">'));
      expect(html, contains('<link rel="alternate" hreflang="x-default" href="$site">'));
      expect(html, contains('<script src="site.js?v='), reason: '${l.code}: the page logic (and the app start) is site.js');
      final graph = jsonLdOf(html)['@graph'] as List;
      final page = graph.firstWhere((e) => (e as Map)['@type'] == 'WebPage') as Map;
      expect(page['url'], l.url);
      expect(page['inLanguage'], l.tag);
      expect(html, isNot(contains(r'$FLUTTER_BASE_HREF')));
    }
    // every page says it in its own words
    final titles = {for (final l in siteLanguages) siteText(l.code).title};
    expect(titles.length, siteLanguages.length);
  });

  test('the old /en/ address redirects to the root, query and all', () {
    final html = File('web/en/index.html').readAsStringSync();
    expect(html, contains('<meta name="robots" content="noindex, follow">'));
    expect(html, contains('<meta http-equiv="refresh" content="0; url=/">'));
    expect(html, contains("location.replace('/' + location.search + location.hash)"), reason: '/en/?example=garden keeps working');
    expect(html, contains('href="$site"'));
    expect(html, isNot(contains('flutter_bootstrap.js')), reason: 'a redirect stub, not a second copy of the app');
  });

  test('manifest.json is valid and every referenced file exists', () {
    final m = jsonDecode(File('web/manifest.json').readAsStringSync()) as Map<String, dynamic>;
    expect(m['name'], startsWith('OpenCADIrrigation'));
    expect(m['theme_color'], '#0D47A1');
    expect(m['lang'], 'en');
    for (final icon in m['icons'] as List) {
      final src = (icon as Map)['src'] as String;
      expect(File('web/$src').existsSync(), isTrue, reason: src);
      final (w, h) = size('web/$src');
      expect('${w}x$h', icon['sizes'], reason: src);
    }
    for (final s in m['screenshots'] as List) {
      expect(File('web/${(s as Map)['src']}').existsSync(), isTrue);
      expect(s['label'], isNotEmpty);
    }
    final urls = (m['shortcuts'] as List).map((s) => (s as Map)['url'] as String).toList();
    expect(urls, contains('./?tutorial=1'));
    expect(urls, contains('./?ai=1'), reason: 'the AI assistant as an app shortcut');
    expect(urls.where((u) => u.contains('example=')), isNotEmpty, reason: 'gallery shortcuts');
    for (final s in m['shortcuts'] as List) {
      expect((s as Map)['url'], anyOf(contains('tutorial=1'), contains('design=1'), contains('ai=1'), contains('example=')));
    }
  });

  test('favicons, touch icon, Open Graph image, robots, sitemap, 404 and CNAME', () {
    expect(File('web/favicon.ico').lengthSync(), greaterThan(1000));
    expect(size('web/favicon-32.png'), (32, 32));
    expect(size('web/favicon-16.png'), (16, 16));
    expect(size('web/apple-touch-icon.png'), (180, 180));
    expect(size('web/og-image.png'), (1200, 630));
    expect(size('web/screenshots/design-1440x900.png'), (1440, 900));
    expect(size('web/brand/logo-square.png').$1, size('web/brand/logo-square.png').$2);
    final robots = File('web/robots.txt').readAsStringSync();
    expect(robots, contains('Sitemap: ${site}sitemap.xml'));
    expect(robots, contains('User-agent: *\nAllow: /'));
    expect(robots, isNot(contains('Disallow')));
    for (final agent in ['GPTBot', 'OAI-SearchBot', 'ClaudeBot', 'Claude-SearchBot', 'PerplexityBot', 'Google-Extended', 'Applebot-Extended', 'CCBot', 'bingbot']) {
      expect(robots, contains('User-agent: $agent\n'), reason: 'AI and search crawlers are welcomed by name');
    }
    expect(robots, contains('${site}llms.txt'));
    final sitemap = File('web/sitemap.xml').readAsStringSync();
    expect(sitemap, contains('<loc>$site</loc>'));
    for (final l in siteLanguages) {
      expect(sitemap, contains('<loc>${l.url}</loc>'), reason: l.code);
    }
    expect(sitemap, contains('<loc>${site}pt/</loc>'));
    expect(sitemap, contains('<loc>${site}de/</loc>'));
    expect(sitemap, isNot(contains('<loc>${site}en/</loc>')), reason: 'English is the root page now');
    expect(sitemap, isNot(contains('?lang=')), reason: 'query URLs are not canonical pages');
    final legalPages = 2 * siteLanguages.where((l) => hasLegalText(l.code)).length;
    expect(RegExp('hreflang="x-default"').allMatches(sitemap).length, siteLanguages.length + legalPages);
    expect(RegExp(r'<lastmod>\d{4}-\d\d-\d\d</lastmod>').allMatches(sitemap).length, siteLanguages.length + legalPages);
    expect(sitemap, contains('<xhtml:link rel="alternate" hreflang="pt" href="${site}pt/"/>'));
    expect(sitemap, contains('<xhtml:link rel="alternate" hreflang="zh" href="${site}zh/"/>'));
    expect(sitemap, contains('<loc>${site}privacy/</loc>'));
    expect(sitemap, isNot(contains('<loc>${site}de/privacy/</loc>')), reason: 'a page still in English is not offered as the German one');
    final notFound = File('web/404.html').readAsStringSync();
    expect(notFound, contains('noindex'));
    for (final l in siteLanguages) {
      expect(notFound, contains('href="${l.url}"'), reason: l.code);
      final section = '<section lang="${l.tag}"${l.rtl ? ' dir="rtl"' : ''} data-lang="${l.code}"';
      expect(notFound, contains(l.code == 'en' ? '$section>' : '$section hidden>'), reason: '${l.code}: English shows unless the browser asks for another language');
    }
    expect(notFound, contains('navigator.languages'));
    expect(File('web/CNAME').readAsStringSync().trim(), 'opencadirrigation.com');
  });

  test('brand assets are bundled with the app', () {
    expect(File('assets/brand/logo-mark.png').existsSync(), isTrue);
    expect(File('assets/brand/logo-horizontal.png').existsSync(), isTrue);
    expect(File('pubspec.yaml').readAsStringSync(), contains('assets/brand/'));
  });

  group('privacy, terms and consent (SIT-01, SIT-13)', () {
    test('every language has a privacy policy and terms of use, linked from the foot of its entry page', () {
      for (final l in siteLanguages) {
        final html = File('web/${l.file}').readAsStringSync();
        final legal = legalText(l.code);
        expect(html, contains('<a href="${privacyUrl(l)}">${legal.privacyLink}</a>'), reason: l.code);
        expect(html, contains('<a href="${termsUrl(l)}">${legal.termsLink}</a>'), reason: l.code);
        for (final privacy in [true, false]) {
          final page = File('web/${l.path}${privacy ? 'privacy' : 'terms'}/index.html').readAsStringSync();
          final url = privacy ? privacyUrl(l) : termsUrl(l);
          final english = privacy ? privacyUrl(siteLang('en')) : termsUrl(siteLang('en'));
          if (hasLegalText(l.code)) {
            expect(page, contains('<html lang="${l.tag}">'), reason: l.code);
            expect(page, contains('<link rel="canonical" href="$url">'), reason: l.code);
            expect(page, contains('<meta name="robots" content="index, follow">'), reason: l.code);
          } else {
            // English for now: says so, is not indexed and points to the English page
            expect(page, contains('<html lang="en">'), reason: l.code);
            expect(page, contains('<link rel="canonical" href="$english">'), reason: l.code);
            expect(page, contains('noindex'), reason: l.code);
          }
          expect(page, contains('href="${l.url}"'), reason: '${l.code}: back to its entry page');
        }
      }
      expect([
        for (final l in siteLanguages)
          if (hasLegalText(l.code)) l.code,
      ], unorderedEquals(['pt', 'en', 'es']));
    });

    test('the privacy policy names the controller, the contact, what is collected and the rights; the terms the licence and the responsibility', () {
      final privacy = File('web/privacy/index.html').readAsStringSync();
      for (final needle in [
        'the maintainer of OpenCADIrrigation',
        'controller',
        '$appRepositoryUrl/issues',
        'Google Analytics 4',
        '_ga_&lt;id&gt;',
        'consent',
        '14 months',
        'Firebase Hosting',
        'fonts.gstatic.com',
        'Nominatim',
        'Anthropic or OpenAI',
        'LGPD',
        'GDPR',
        'ANPD',
        'never while the app is open',
      ]) {
        expect(privacy, contains(needle), reason: needle);
      }
      final terms = File('web/terms/index.html').readAsStringSync();
      for (final needle in ['MIT licence', '&quot;as is&quot;', 'qualified professional', 'technical responsibility', 'ART', 'data sheets']) {
        expect(terms, contains(needle), reason: needle);
      }
      final pt = File('web/pt/terms/index.html').readAsStringSync();
      expect(pt, contains('profissional habilitado'));
      expect(pt, contains('respectiva ART'));
      expect(File('web/pt/privacy/index.html').readAsStringSync(), contains('mantenedor do OpenCADIrrigation'));
    });

    test('no page loads the statistics by itself: site.js asks first and never loads them where the app runs', () {
      final pages = [
        for (final e in renderSite().entries)
          if (e.key.endsWith('.html')) e.value,
      ];
      for (final html in pages) {
        expect(html, isNot(contains('googletagmanager.com/gtag')), reason: 'gtag.js is loaded by site.js after consent only');
      }
      final script = File('web/site.js').readAsStringSync();
      // Consent Mode v2: denied by default, only the statistics granted
      expect(script, contains("'consent', 'default', { ad_storage: 'denied', ad_user_data: 'denied', ad_personalization: 'denied', analytics_storage: 'denied' }"));
      expect(script, contains("'consent', 'update', { analytics_storage: 'granted' }"));
      expect(script.indexOf("'consent', 'default'"), lessThan(script.indexOf("tag.src = 'https://www.googletagmanager.com/gtag/js?id='")));
      // loaded only after the visitor's answer, and never in a page where the app started
      expect(script, contains('if (analytics || started || !analyticsId) return;'));
      expect(RegExp(r'loadAnalytics\(\)').allMatches(script).length, 3, reason: 'the definition, Accept and a stored Accept');
      expect(script, contains("if (answer === 'granted') loadAnalytics();"));
      // the answer is not stored under the app's prefix: answering the notice is not using the app
      final key = RegExp(r"var consentKey = '([^']+)';").firstMatch(script)!.group(1)!;
      expect(key.startsWith('opencadirrigation.'), isFalse);
      // declining deletes the cookies; the notice comes back from the foot of every page
      expect(script, contains('dropCookies();'));
      for (final l in siteLanguages) {
        final html = File('web/${l.file}').readAsStringSync();
        expect(html, contains('id="oci-consent"'), reason: l.code);
        expect(html, contains('data-consent="granted"'), reason: l.code);
        expect(html, contains('data-consent="denied"'), reason: l.code);
        expect(html, contains('data-consent-open'), reason: l.code);
        expect(html.indexOf('id="oci-consent"'), lessThan(html.indexOf('</main>')), reason: '${l.code}: the notice is part of the landing, hidden with it when the app starts');
      }
    });

    test('the statistics can be left out of a fork: no measurement id, no notice', () {
      expect(analyticsId, matches(RegExp(r'^G-[A-Z0-9]+$')));
      expect(File('tool/site.dart').readAsStringSync(), contains("Platform.environment['OCI_ANALYTICS_ID']"));
    });
  });

  test('every own page carries the Content Security Policy before any script, and no inline script runs (ENG-06)', () {
    for (final e in renderSite().entries) {
      final isOwnPage = e.key.endsWith('index.html') && e.key != 'en/index.html';
      if (!isOwnPage) continue;
      final html = e.value;
      final meta = '<meta http-equiv="Content-Security-Policy" content="$contentSecurityPolicy">';
      expect(html, contains(meta), reason: e.key);
      expect(html.indexOf(meta), lessThan(html.indexOf('<script')), reason: '${e.key}: before every script');
      for (final m in RegExp(r'<script([^>]*)>').allMatches(html)) {
        final attrs = m.group(1)!;
        expect(attrs.contains(' src=') || attrs.contains('type="application/ld+json"'), isTrue, reason: '${e.key}: inline script <script$attrs>');
      }
    }
    for (final directive in ["script-src 'self' 'wasm-unsafe-eval'", "object-src 'none'", "base-uri 'self'", "worker-src 'self'", "frame-src 'none'"]) {
      expect(contentSecurityPolicy, contains(directive));
    }
    expect(contentSecurityPolicy, isNot(contains("'unsafe-eval'")));
    expect(contentSecurityPolicy, isNot(contains("script-src 'self' 'unsafe-inline'")));
  });

  test('the hosting configuration: security headers, revalidated app files and the /en/ redirect (ENG-05, SIT-19, SIT-22)', () {
    final hosting = jsonDecode(File('hosting/firebase.json').readAsStringSync())['hosting'] as Map<String, dynamic>;
    expect(hosting['public'], 'public');
    final rules = [for (final r in hosting['headers'] as List) r as Map<String, dynamic>];
    Map<String, String> headersOf(String source) => {for (final h in rules.firstWhere((r) => r['source'] == source)['headers'] as List) (h as Map)['key'] as String: h['value'] as String};
    final all = headersOf('**');
    expect(all['X-Content-Type-Options'], 'nosniff');
    expect(all['Referrer-Policy'], 'strict-origin-when-cross-origin');
    expect(all['Permissions-Policy'], contains('geolocation=(self)'));
    expect(all['Permissions-Policy'], contains('microphone=(self)'));
    expect(all['Permissions-Policy'], contains('camera=()'));
    // the app files without a version in their names are revalidated, never kept an hour
    final revalidated = [
      for (final r in rules)
        if ((r['headers'] as List).any((h) => (h as Map)['value'] == 'no-cache')) r['source'] as String,
    ];
    for (final needle in ['main.dart.js', 'design_worker.js', 'site.js', 'sw.js', 'flutter_bootstrap.js', '*.part.js', '@(assets|canvaskit)/**', '**/manifest.json']) {
      expect(revalidated.any((s) => s.contains(needle)), isTrue, reason: needle);
    }
    final redirects = [for (final r in hosting['redirects'] as List) r as Map<String, dynamic>];
    expect(redirects.where((r) => r['source'] == '/en/' && r['destination'] == '/' && r['type'] == 301), hasLength(1));
    // site.js sends new visitors from the default addresses of the project to the site's own
    final script = File('web/site.js').readAsStringSync();
    expect(script, contains('"$firebaseProjectId.web.app","$firebaseProjectId.firebaseapp.com"'));
    expect(script, contains('&& !usedHere()'), reason: 'whoever has projects stored on that address stays');
  });

  test('each entry page has a manifest in its language, with the same identity and a start address of its own (SIT-12)', () {
    for (final l in siteLanguages) {
      final html = File('web/${l.file}').readAsStringSync();
      expect(html, contains('<link rel="manifest" href="${l.path}manifest.json">'), reason: l.code);
      final m = jsonDecode(File('web/${l.path}manifest.json').readAsStringSync()) as Map<String, dynamic>;
      final t = siteText(l.code);
      expect(m['lang'], l.tag, reason: l.code);
      expect(m['dir'], l.dir, reason: l.code);
      expect(m['description'], t.description, reason: l.code);
      expect(m['start_url'], './?source=pwa', reason: '${l.code}: the start address is the page of the language');
      expect(Uri.parse('${l.url}manifest.json').resolve(m['id'] as String).toString(), site, reason: '${l.code}: one app whatever the language it was installed from');
      expect(Uri.parse('${l.url}manifest.json').resolve(m['scope'] as String).toString(), site, reason: l.code);
      expect([for (final s in m['shortcuts'] as List) (s as Map)['name']], contains(t.tutorial), reason: l.code);
      final forms = [for (final s in m['screenshots'] as List) (s as Map)['form_factor']];
      expect(forms, containsAll(['wide', 'narrow']), reason: '${l.code}: phones show the full install sheet');
      for (final s in [...m['icons'] as List, ...m['screenshots'] as List]) {
        final src = Uri.parse('${l.url}manifest.json').resolve((s as Map)['src'] as String).path.substring(1);
        expect(File('web/$src').existsSync(), isTrue, reason: '${l.code}: $src');
      }
    }
    final (w, h) = size('web/screenshots/phone-780x1688.png');
    expect((w, h), (780, 1688));
  });

  test('the FAQ no longer promises that the internet is reached only on request (SIT-02)', () {
    final en = siteText('en');
    final cloud = en.faq.indexWhere((f) => f.$1 == 'Are my projects stored in the cloud?');
    expect(en.faq[cloud].$2, faqCloudAnswerEn);
    for (final needle in ['Google Fonts', 'Google Analytics only if you accept it', 'never while the app is open', 'privacy policy']) {
      expect(faqCloudAnswerEn, contains(needle));
    }
    for (final l in siteLanguages) {
      final a = siteText(l.code).faq[cloud].$2;
      expect(a, contains('Google Analytics'), reason: '${l.code}: the statistics are named');
      expect(a.toLowerCase(), isNot(contains('only when you ask')), reason: l.code);
    }
    final llms = File('web/llms-full.txt').readAsStringSync();
    expect(llms, isNot(contains('reached only when the user asks')));
    expect(llms, contains('${site}privacy/'));
  });
}
